import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { ghostBordered, glyphBtn } from './classes';

const css = readFileSync(new URL('./styles.css', import.meta.url), 'utf8');

describe('src/styles.css', () => {
  // Generated by /ship on 2026-10-20 (ghostBordered copies the base hover border)
  // Value: protects=the bordered ghost buttons (Settings arrows and rarity Remove, the Maxed ✕) hover with the same border as
  // every other button, on wider screens and enabled buttons only; fails_when=the base hover rule in styles.css changes
  // its color or condition and ghostBordered isn't changed with it, or the glyph buttons stop using ghostBordered;
  // why_new=the two only agreed by comment; seam=none; no_claim=how the border looks (checked in a real browser)
  it('keeps the base button hover border and ghostBordered in step', () => {
    const base = /@media \(min-width: 768px\) and \(hover: hover\) \{\s*button:not\(:disabled\):hover \{\s*border-color: var\(--color-(\w+)\);/.exec(css);
    expect([base?.[1], ghostBordered.split(' ').includes(`md:enabled:hover:border-${base?.[1]}`), glyphBtn.startsWith(ghostBordered)]).toEqual(['muted', true, true]);
  });
});
